<script lang="ts">
 import ParkRadarChart from './ParkRadarChart.svelte'; import type { Park } from '../types/park';
 let {park,pinned,onClose,context='consumer'}:{park:Park|null;pinned:boolean;onClose:()=>void;context?:'consumer'|'municipality'}=$props();
 const value=(v:boolean|null|string)=>v===null?'Unknown':typeof v==='boolean'?(v?'Yes':'No'):v[0].toUpperCase()+v.slice(1);
 const attrs=(p:Park)=>[['Bench',p.bench],['Toilet',p.toilet],['Water tap access',p.waterTapAccess],['Playground',p.playground],['Public sport park',p.publicSportPark],['Football & sport courts',p.footballSportCourts],['Dog off-leash area',p.dogOffLeashArea],['Canopy cover',p.canopyCover],['Grass cover',p.grassCover],['Wheelchair accessible',p.wheelchairAccessible],['Crossings',p.crossings],['Traffic light',p.trafficLight],['Street / Park light',p.streetParkLight],['Fenced area',p.fencedArea]] as const;
</script>
<aside class:visible={park!==null} class="details" aria-live="polite">{#if park}<div class="details-top"><span class="pill">{pinned?'Pinned park':'Previewing'}</span><button onclick={onClose} aria-label="Unpin and close park details">×</button></div><p class="eyebrow">Demo data · {context==='consumer'?'Park profile':'Municipality review'}</p><h2>{park.name}</h2><p class="description">{park.description}</p><div class="access-badge">Public access: <strong>{value(park.publicAccess)}</strong></div><h3>Park character</h3><ParkRadarChart {park}/><p class="chart-note">Six dimensions: canopy and grass use Low=1, Mid=2, High=3; recorded Yes=3 and No=0. Gaps mean Unknown. Public access is separate.</p><h3>All 15 attributes</h3><dl class="attribute-grid">{#each attrs(park) as attr}<div class:unknown={attr[1]===null} class:yes={attr[1]===true} class:no={attr[1]===false} class:level={typeof attr[1]==='string'}><dt>{attr[0]}</dt><dd>{typeof attr[1]==='boolean'?(attr[1]?'✓':'–'):attr[1]===null?'?':''} {value(attr[1])}</dd></div>{/each}<div class="level"><dt>Opening hours / Public access</dt><dd>{value(park.publicAccess)}</dd></div></dl>{:else}<div class="empty-detail"><div class="leaf" aria-hidden="true">⌁</div><h2>Discover a park</h2><p>Hover over a marker to preview a park, or select one to keep its details open.</p></div>{/if}</aside>
